uint64_t read_counter(const volatile uint32_t* hi, const volatile uint32_t* lo) {
  uint32_t h1, l, h2;
  do {
    h1 = *hi;   // volatile: every read really happens, in this order
    l  = *lo;
    h2 = *hi;
  } while (h1 != h2);  // HI changed: LO may belong to either value, retry
  return (uint64_t(h1) << 32) | l;
}
// Correct because if HI did not change between the two reads, LO was read
// while HI == h1, so (h1, l) is a value the counter really had.
// Retries are rare: at most once per 2^32 ticks of LO wrapping.
// Assumes accesses to one device are not reordered (true for UC and
// ARM Device-nR); if the datasheet says reading LO latches HI, read LO first.
